480	    fn visit_jsx_element(&mut self, element: &JSXElement<'a>) {

1	//! The ordered set of analyzers that decides which one owns a path.
2	
3	use std::sync::Arc;
4	
5	use camino::Utf8Path;
6	
7	use super::lang::{LanguageAnalyzer, LanguageId};
8	
9	/// Analyzers in registration order.
10	///
11	/// Callers ask the registry which analyzer owns a file instead of naming a concrete analyzer.
12	///
13	/// # Examples
14	///
15	/// ```
16	/// use monokl::analysis::registry::AnalyzerRegistry;
17	///
18	/// let registry = AnalyzerRegistry::new(Vec::new());
19	/// assert!(registry.analyzer_for("a.ts".into()).is_none());
20	/// ```
21	pub struct AnalyzerRegistry {
22	    analyzers: Vec<Arc<dyn LanguageAnalyzer>>,
23	}
24	
25	impl AnalyzerRegistry {
26	    /// Builds a registry that consults `analyzers` in the given order.
27	    pub fn new(analyzers: Vec<Arc<dyn LanguageAnalyzer>>) -> Self {
28	        Self { analyzers }
29	    }
30	
31	    /// Returns the first registered analyzer whose [`LanguageAnalyzer::supports`] accepts `path`.
32	    ///
33	    /// # Examples
34	    ///
35	    /// ```
36	    /// use monokl::analysis::registry::AnalyzerRegistry;
37	    ///
38	    /// assert!(AnalyzerRegistry::new(Vec::new()).analyzer_for("a.ts".into()).is_none());
39	    /// ```
40	    pub fn analyzer_for(&self, path: &Utf8Path) -> Option<&dyn LanguageAnalyzer> {
41	        self.analyzers.iter().find(|analyzer| analyzer.supports(path)).map(Arc::as_ref)
42	    }
43	
44	    /// Returns whether the analyzer that owns `path` reports one of `languages` for it.
45	    ///
46	    /// # Examples
47	    ///
48	    /// ```
49	    /// use monokl::analysis::LanguageId;
50	    /// use monokl::analysis::registry::AnalyzerRegistry;
51	    ///
52	    /// let registry = AnalyzerRegistry::new(Vec::new());
53	    /// assert!(!registry.supports_language("a.ts".into(), &[LanguageId::TypeScript]));
54	    /// ```
55	    pub fn supports_language(&self, path: &Utf8Path, languages: &[LanguageId]) -> bool {
56	        self.analyzer_for(path)
57	            .and_then(|analyzer| analyzer.language_for(path))
58	            .is_some_and(|language| languages.contains(&language))
59	    }
60	}
