25	/// Files nested deeper than this are not parsed: the parser recurses once per level and overflowing the stack aborts
26	/// the process. A 2 MiB debug-build stack, the tightest a worker thread is likely to have, overflows between 700 and
27	/// 850 nested arrays; real code stays far below this.
28	const MAX_SOURCE_NESTING_DEPTH: usize = 256;
29	
30	/// Everything extracted from one file, before it is wrapped in a `FileAnalysis`.
31	#[derive(Debug, Default)]
32	pub(super) struct Extraction {
33	    pub(super) symbols: Vec<SymbolEntry>,
34	    pub(super) dependencies: Vec<DependencyRecord>,
35	    pub(super) exports: Vec<ExportRecord>,
36	    pub(super) blocks: Vec<CodeBlock>,
37	    pub(super) jsx_elements: Vec<JsxElementEntry>,
38	    pub(super) type_only_imports: Vec<String>,
39	    pub(super) had_parse_errors: bool,
40	}
41	
42	impl Extraction {
43	    /// The result for a file that could not be analyzed: no data, flagged as having errors.
44	    fn degraded() -> Self {
45	        Self { had_parse_errors: true, ..Self::default() }
46	    }
47	}
48	
49	/// Extracts what `profile` asks for from `source`.
50	///
51	/// A file nested too deeply to parse safely, or one whose parse or extraction panics, yields
52	/// [`Extraction::degraded`].
53	pub(super) fn extract(path: &Utf8Path, source: &str, profile: AnalysisProfile) -> Extraction {
54	    if max_bracket_nesting_depth(source) > MAX_SOURCE_NESTING_DEPTH {
55	        return Extraction::degraded();
56	    }
57	    guarded(|| parse_and_extract(path, source, profile))
58	}
59	
60	fn guarded(run: impl FnOnce() -> Extraction) -> Extraction {
61	    // The closure's output is discarded on a panic, so no torn state is observable afterwards.
62	    catch_unwind(AssertUnwindSafe(run)).unwrap_or_else(|_| Extraction::degraded())
63	}
64	
65	/// The deepest bracket nesting in `source`, skipping comments and string literals.
66	///
67	/// A cheap linear scan used as a proxy for how deep the parser will recurse. It undercounts around apostrophes in
68	/// JSX text and regex literals, which only ever lets a file through, never rejects a valid one.
69	fn max_bracket_nesting_depth(source: &str) -> usize {
70	    let bytes = source.as_bytes();
71	    let (mut depth, mut max_depth, mut i) = (0usize, 0usize, 0usize);
72	    while i < bytes.len() {
73	        match bytes[i] {
74	            b'/' if bytes.get(i + 1) == Some(&b'/') => {
75	                while i < bytes.len() && bytes[i] != b'\n' {
76	                    i += 1;
77	                }
78	            }
79	            b'/' if bytes.get(i + 1) == Some(&b'*') => {
80	                i += 2;
81	                while i + 1 < bytes.len() && !(bytes[i] == b'*' && bytes[i + 1] == b'/') {
82	                    i += 1;
83	                }
84	                i += 2;
85	            }
86	            quote @ (b'\'' | b'"' | b'`') => {
87	                i += 1;
88	                while i < bytes.len() && bytes[i] != quote {
89	                    i += if bytes[i] == b'\\' { 2 } else { 1 };
90	                }
91	                i += 1;
92	            }
93	            b'(' | b'{' | b'[' => {
94	                depth += 1;
95	                max_depth = max_depth.max(depth);
96	                i += 1;
97	            }
98	            b')' | b'}' | b']' => {
99	                depth = depth.saturating_sub(1);
100	                i += 1;
101	            }
102	            _ => i += 1,
103	        }
104	    }
105	    max_depth
106	}
