67	    use crate::error::{MonoklError, Result};
68	
69	    /// Claims every path ending in `extension` and reports its one language for it.
70	    struct ByExtension {
71	        extension: &'static str,
72	        languages: [LanguageId; 1],
73	    }
74	
75	    impl LanguageAnalyzer for ByExtension {
76	        fn languages(&self) -> &[LanguageId] {
77	            &self.languages
78	        }
79	        fn supports(&self, path: &Utf8Path) -> bool {
80	            path.extension() == Some(self.extension)
81	        }
82	        fn language_for(&self, path: &Utf8Path) -> Option<LanguageId> {
83	            self.supports(path).then_some(self.languages[0])
84	        }
85	        fn capabilities(&self, _language: LanguageId) -> AnalyzerCapabilities {
86	            AnalyzerCapabilities {
87	                blocks: true,
88	                classified_imports: false,
89	                resolved_import_graph: CapabilityPrecision::Unsupported,
90	                refs: CapabilityPrecision::Unsupported,
91	                definition: CapabilityPrecision::Unsupported,
92	                inspect_detail: CapabilityPrecision::Unsupported,
93	            }
94	        }
