97	            _path: &Utf8Path,
98	            _source: Box<dyn FnOnce() -> Result<String>>,
99	            _profile: AnalysisProfile,
100	        ) -> Result<Arc<FileAnalysis>> {
101	            Err(MonoklError::TooManyTerms { count: 0, limit: 0 })
102	        }
103	    }
