112	            analyzer("ts", LanguageId::TypeScript),
113	            analyzer("rs", LanguageId::Rust),
114	            analyzer("ts", LanguageId::Go),
115	        ]);
116	        let owner = registry.analyzer_for(Utf8Path::new("src/a.ts")).unwrap();
117	        assert_eq!(owner.languages(), [LanguageId::TypeScript]);
