5	/// How a term affects matching: `+` requires it, `-` excludes it, and a bare term is optional and scored.
6	#[derive(Debug, Clone, PartialEq, Eq)]
7	pub enum Modifier {
8	    Required,
9	    Excluded,
10	    Optional,
11	}
12	
13	/// A single query term.
14	///
15	/// `pattern` is a regex: the user's text escaped as a literal, or the raw text after a `regex:` prefix.
16	#[derive(Debug, Clone)]
17	pub struct ParsedTerm {
18	    pub modifier: Modifier,
19	    pub pattern: String,
20	    pub is_regex: bool,
21	}
22	
23	/// Parses a query string into terms.
24	///
25	/// Malformed input is tolerated rather than rejected: a dangling `+`, `-`, or `regex:` yields no term, and a modifier
26	/// followed by `regex:` drops both the modifier and the regex prefix. Regex syntax is not validated here.
27	///
28	/// # Errors
29	///
30	/// Returns [`MonoklError::TooManyTerms`] if the query has more than 64 terms.
31	pub fn parse(input: &str) -> Result<Vec<ParsedTerm>> {
32	    const LIMIT: usize = 64;
33	    if input.trim().is_empty() {
34	        return Ok(Vec::new());
35	    }
36	    let mut lexer = Lexer::new(input);
37	    let mut terms: Vec<ParsedTerm> = Vec::new();
38	    loop {
39	        let tok = lexer.next_token();
40	        match tok {
41	            Token::Eof => break,
42	            Token::Plus => {
43	                let content = lexer.next_token();
44	                if let Some(term) = content_to_term(content, Modifier::Required) {
45	                    terms.push(term);
46	                }
47	            }
48	            Token::Minus => {
49	                let content = lexer.next_token();
50	                if let Some(term) = content_to_term(content, Modifier::Excluded) {
51	                    terms.push(term);
52	                }
53	            }
54	            Token::RegexPrefix => {
55	                let pattern_tok = lexer.next_token();
56	                match pattern_tok {
57	                    Token::Word(raw) | Token::QuotedString(raw) => {
58	                        terms.push(ParsedTerm { modifier: Modifier::Optional, pattern: raw, is_regex: true });
59	                    }
60	                    _ => {}
61	                }
62	            }
63	            Token::Word(w) => {
64	                terms.push(ParsedTerm { modifier: Modifier::Optional, pattern: regex::escape(&w), is_regex: false });
65	            }
66	            Token::QuotedString(s) => {
67	                terms.push(ParsedTerm { modifier: Modifier::Optional, pattern: regex::escape(&s), is_regex: false });
68	            }
69	        }
70	    }
71	    if terms.len() > LIMIT {
72	        return Err(MonoklError::TooManyTerms { count: terms.len(), limit: LIMIT });
73	    }
74	    Ok(terms)
75	}
76	
77	fn content_to_term(tok: Token, modifier: Modifier) -> Option<ParsedTerm> {
78	    match tok {
79	        Token::Word(w) => Some(ParsedTerm { modifier, pattern: regex::escape(&w), is_regex: false }),
80	        Token::QuotedString(s) => Some(ParsedTerm { modifier, pattern: regex::escape(&s), is_regex: false }),
81	        // `+regex:foo` loses its modifier here, and the main loop then reads `foo` as a bare optional word.
82	        Token::RegexPrefix | Token::Plus | Token::Minus | Token::Eof => None,
83	    }
84	}
