1	//! Partitioning of parsed query terms into required, excluded, and scored groups.
2	use super::parser::{Modifier, ParsedTerm};
3	
4	/// A parsed query split by modifier.
5	///
6	/// The index vectors point into `terms` and keep each group's original relative order.
7	#[derive(Debug, Clone)]
8	pub struct QueryPlan {
9	    pub terms: Vec<ParsedTerm>,
10	    pub required: Vec<usize>,
11	    pub excluded: Vec<usize>,
12	    pub scored: Vec<usize>,
13	}
14	
15	impl QueryPlan {
16	    /// Partitions `terms` by modifier.
17	    pub fn from_terms(terms: Vec<ParsedTerm>) -> Self {
18	        let required: Vec<usize> =
19	            terms.iter().enumerate().filter(|(_, t)| t.modifier == Modifier::Required).map(|(i, _)| i).collect();
20	        let excluded: Vec<usize> =
21	            terms.iter().enumerate().filter(|(_, t)| t.modifier == Modifier::Excluded).map(|(i, _)| i).collect();
22	        let scored: Vec<usize> =
23	            terms.iter().enumerate().filter(|(_, t)| t.modifier == Modifier::Optional).map(|(i, _)| i).collect();
24	        Self { terms, required, excluded, scored }
25	    }
26	
27	    /// Returns whether the plan has no terms at all, including excluded ones.
28	    pub fn is_empty(&self) -> bool {
29	        self.terms.is_empty()
30	    }
31	
32	    /// Returns the required patterns followed by the scored patterns.
33	    ///
34	    /// # Panics
35	    ///
36	    /// Panics if `required` or `scored` holds an index outside `terms`, which only a hand-built plan can do.
37	    pub fn search_patterns(&self) -> Vec<&str> {
38	        self.required.iter().chain(self.scored.iter()).map(|&i| self.terms[i].pattern.as_str()).collect()
39	    }
40	}
