66	/// Splits source text on every character other than `[A-Za-z0-9_]` and tokenizes each fragment with [`tokenize`].
67	///
68	/// Duplicates are kept in source order, since BM25 needs term frequency.
69	///
70	/// # Examples
71	///
72	/// ```
73	/// use monokl::tokens::tokenize_source;
74	///
75	/// assert_eq!(tokenize_source("fooBar(fooBar)"), ["foo", "bar", "foo", "bar"]);
76	/// ```
77	pub fn tokenize_source(source: &str) -> Vec<String> {
78	    source
79	        .split(|ch: char| !(ch.is_ascii_alphanumeric() || ch == '_'))
80	        .filter(|fragment| !fragment.is_empty())
81	        .flat_map(tokenize)
82	        .collect()
83	}
