1	//! Algorithm-prefixed content digests, written `algorithm:hex` (the OCI descriptor digest grammar).
2	
3	use std::fmt;
4	use std::str::FromStr;
5	
6	/// The hash algorithm a [`Digest`] was computed with.
7	///
8	/// The set is closed, so a `match` needs no wildcard arm. Adding an algorithm is a breaking change.
9	///
10	/// # Examples
11	///
12	/// ```
13	/// use monokl::digest::DigestAlgorithm;
14	///
15	/// fn hex_len(algorithm: DigestAlgorithm) -> usize {
16	///     match algorithm {
17	///         DigestAlgorithm::Sha256 => 64,
18	///         DigestAlgorithm::Blake3 => 64,
19	///     }
20	/// }
21	/// assert_eq!(hex_len(DigestAlgorithm::Blake3), 64);
22	/// ```
23	#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
24	pub enum DigestAlgorithm {
25	    Sha256,
26	    Blake3,
27	}
28	
29	/// A 32-byte digest that names its algorithm, so a change of algorithm never collides with old values.
30	#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
31	pub struct Digest {
32	    pub algorithm: DigestAlgorithm,
33	    pub bytes: [u8; 32],
34	}
35	
36	/// Why a string is not a valid [`Digest`].
37	#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
38	#[non_exhaustive]
39	pub enum DigestParseError {
40	    #[error("digest has no `:` between algorithm and hex")]
41	    MissingSeparator,
42	    #[error("unknown digest algorithm {algorithm:?}")]
43	    UnknownAlgorithm { algorithm: String },
44	    #[error("digest hex must be 64 lowercase hex characters")]
45	    InvalidEncoding,
46	}
47	
48	impl DigestAlgorithm {
49	    /// Returns the name used before the `:` in a digest's text form.
50	    ///
51	    /// # Examples
52	    ///
53	    /// ```
54	    /// use monokl::digest::DigestAlgorithm;
55	    ///
56	    /// assert_eq!(DigestAlgorithm::Blake3.as_str(), "blake3");
57	    /// assert_eq!(DigestAlgorithm::Sha256.as_str(), "sha256");
58	    /// ```
59	    #[must_use]
60	    pub fn as_str(self) -> &'static str {
61	        match self {
62	            Self::Sha256 => "sha256",
63	            Self::Blake3 => "blake3",
64	        }
65	    }
66	}
67	
68	/// Parses exactly `sha256` or `blake3`; any other spelling, including a different case, is
69	/// [`DigestParseError::UnknownAlgorithm`].
70	///
71	/// # Examples
72	///
73	/// ```
74	/// use monokl::digest::{DigestAlgorithm, DigestParseError};
75	///
76	/// assert_eq!("blake3".parse(), Ok(DigestAlgorithm::Blake3));
77	/// assert_eq!(
78	///     "Blake3".parse::<DigestAlgorithm>(),
79	///     Err(DigestParseError::UnknownAlgorithm { algorithm: "Blake3".to_string() })
80	/// );
81	/// ```
82	impl FromStr for DigestAlgorithm {
83	    type Err = DigestParseError;
84	
85	    fn from_str(s: &str) -> Result<Self, Self::Err> {
86	        match s {
87	            "sha256" => Ok(Self::Sha256),
88	            "blake3" => Ok(Self::Blake3),
89	            other => Err(DigestParseError::UnknownAlgorithm { algorithm: other.to_string() }),
90	        }
91	    }
92	}
93	
94	impl Digest {
95	    /// Hashes `content` with blake3.
96	    ///
97	    /// # Examples
98	    ///
99	    /// ```
100	    /// use monokl::digest::Digest;
101	    ///
102	    /// let d = Digest::blake3(b"");
103	    /// assert_eq!(d.to_string(), "blake3:af1349b9f5f9a1a6a0404dea36dcc9499bcb25c9adc112b7cc9a93cae41f3262");
104	    /// ```
105	    #[must_use]
106	    pub fn blake3(content: &[u8]) -> Self {
107	        Self { algorithm: DigestAlgorithm::Blake3, bytes: *blake3::hash(content).as_bytes() }
108	    }
109	}
110	
111	const HEX_DIGITS: &[u8; 16] = b"0123456789abcdef";
112	
113	impl fmt::Display for Digest {
114	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
115	        use fmt::Write as _;
116	        f.write_str(self.algorithm.as_str())?;
117	        f.write_char(':')?;
118	        for byte in self.bytes {
119	            f.write_char(char::from(HEX_DIGITS[usize::from(byte >> 4)]))?;
120	            f.write_char(char::from(HEX_DIGITS[usize::from(byte & 0x0f)]))?;
121	        }
122	        Ok(())
123	    }
124	}
125	
126	/// Parses `algorithm:hex`, checking the separator, then the algorithm, then the hex. Nothing is trimmed.
127	///
128	/// # Examples
129	///
130	/// ```
131	/// use monokl::digest::{Digest, DigestParseError};
132	///
133	/// let text = "blake3:af1349b9f5f9a1a6a0404dea36dcc9499bcb25c9adc112b7cc9a93cae41f3262";
134	/// assert_eq!(text.parse(), Ok(Digest::blake3(b"")));
135	/// assert_eq!("md5:zz".parse::<Digest>(), Err(DigestParseError::UnknownAlgorithm { algorithm: "md5".to_string() }));
136	/// ```
137	impl FromStr for Digest {
138	    type Err = DigestParseError;
139	
140	    fn from_str(s: &str) -> Result<Self, Self::Err> {
141	        let Some((algorithm, encoded)) = s.split_once(':') else {
142	            return Err(DigestParseError::MissingSeparator);
143	        };
144	        let algorithm = algorithm.parse()?;
145	        let (pairs, []) = encoded.as_bytes().as_chunks::<2>() else {
146	            return Err(DigestParseError::InvalidEncoding);
147	        };
148	        if pairs.len() != 32 {
149	            return Err(DigestParseError::InvalidEncoding);
150	        }
151	        let mut bytes = [0u8; 32];
152	        for (byte, [high, low]) in bytes.iter_mut().zip(pairs) {
153	            *byte = (lowercase_hex_value(*high)? << 4) | lowercase_hex_value(*low)?;
154	        }
155	        Ok(Self { algorithm, bytes })
156	    }
157	}
158	
159	/// Uppercase is rejected: OCI forbids it, and a digest whose case can vary breaks equality and hashing.
160	fn lowercase_hex_value(c: u8) -> Result<u8, DigestParseError> {
161	    match c {
162	        b'0'..=b'9' => Ok(c - b'0'),
163	        b'a'..=b'f' => Ok(c - b'a' + 10),
164	        _ => Err(DigestParseError::InvalidEncoding),
165	    }
166	}
