170	        serializer.collect_str(self)

1	//! Removes ranked blocks that mostly repeat a better-ranked block in the same file.
2	
3	use crate::types::{CodeBlock, RankedBlock};
4	
5	/// Drops each block that overlaps an earlier kept block in the same file by more than half of the smaller block's
6	/// lines, then reassigns 1-based ranks.
7	///
8	/// The input is expected best first, as [`rank_blocks`](crate::rank::rank_blocks) returns it, so the better block of
9	/// an overlapping pair survives. Blocks in different files never dedupe. A block whose `line_end` is before its
10	/// `line_start` overlaps nothing and is always kept.
11	///
12	/// # Examples
13	///
14	/// ```
15	/// use camino::Utf8PathBuf;
16	/// use monokl::dedup::dedup_blocks;
17	/// use monokl::types::{CodeBlock, RankedBlock, SymbolKind};
18	///
19	/// let ranked = |line_start, line_end, rank| RankedBlock {
20	///     block: CodeBlock {
21	///         file: Utf8PathBuf::from("src/a.ts"),
22	///         line_start,
23	///         line_end,
24	///         node_kind: SymbolKind::Function,
25	///         code: String::new(),
26	///         symbol_signature: None,
27	///         matched_lines: Vec::new(),
28	///         matched_keywords: Vec::new(),
29	///     },
30	///     bm25_score: 0.0,
31	///     coverage_boost: 0.0,
32	///     node_type_boost: 1.5,
33	///     final_score: 0.0,
34	///     rank,
35	///     parent_context: None,
36	/// };
37	/// let kept = dedup_blocks(vec![ranked(1, 10, 1), ranked(5, 10, 2), ranked(20, 30, 3)]);
38	/// let kept: Vec<_> = kept.iter().map(|r| (r.block.line_start, r.rank)).collect();
39	/// assert_eq!(kept, [(1, 1), (20, 2)]);
40	/// ```
41	pub fn dedup_blocks(blocks: Vec<RankedBlock>) -> Vec<RankedBlock> {
42	    let mut kept: Vec<RankedBlock> = Vec::with_capacity(blocks.len());
43	    for block in blocks {
44	        let is_duplicate = kept.iter().any(|earlier| {
45	            earlier.block.file == block.block.file && overlaps_significantly(&earlier.block, &block.block)
46	        });
47	        if !is_duplicate {
48	            kept.push(block);
49	        }
50	    }
51	    for (rank, block) in (1..).zip(&mut kept) {
52	        block.rank = rank;
53	    }
54	    kept
55	}
56	
57	/// Returns whether the two line ranges share more than half of the smaller range's lines.
58	fn overlaps_significantly(a: &CodeBlock, b: &CodeBlock) -> bool {
59	    let overlap_start = a.line_start.max(b.line_start);
60	    let overlap_end = a.line_end.min(b.line_end);
61	    if overlap_start > overlap_end {
62	        return false;
63	    }
64	    let overlap_lines = overlap_end - overlap_start + 1;
65	    // Nothing guarantees `line_start <= line_end`, so the lengths saturate rather than risk an underflow panic.
66	    let smaller_len = (a.line_end.saturating_sub(a.line_start) + 1).min(b.line_end.saturating_sub(b.line_start) + 1);
67	    overlap_lines * 2 > smaller_len
68	}
