4	/// Returns the fraction of the block's matched lines that fall inside `line_start..=line_end`, rounded with
5	/// [`round6`].
6	///
7	/// Returns 0.0 when `matched_lines` is empty. A block whose `line_end` is before its `line_start` contains no lines.
8	///
9	/// # Examples
10	///
11	/// ```
12	/// use camino::Utf8PathBuf;
13	/// use monokl::rank::coverage_boost;
14	/// use monokl::types::{CodeBlock, SymbolKind};
15	///
16	/// let block = CodeBlock {
17	///     file: Utf8PathBuf::from("src/a.ts"),
18	///     line_start: 10,
19	///     line_end: 20,
20	///     node_kind: SymbolKind::Function,
21	///     code: String::new(),
22	///     symbol_signature: None,
23	///     matched_lines: vec![12, 30, 40],
24	///     matched_keywords: Vec::new(),
25	/// };
26	/// assert_eq!(coverage_boost(&block), 0.333333);
27	/// ```
28	pub fn coverage_boost(block: &CodeBlock) -> f64 {
29	    if block.matched_lines.is_empty() {
30	        return 0.0;
31	    }
32	    let lines = block.line_start..=block.line_end;
33	    let inside = block.matched_lines.iter().filter(|line| lines.contains(*line)).count();
34	    round6(as_f64(inside) / as_f64(block.matched_lines.len()))
35	}
